import{_ as e,o,c as t,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Painel de resumo da minuta","description":"","frontmatter":{"title":"Painel de resumo da minuta","id":"eproc-resumo-minuta-flutuante","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.1.3","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-resumo-minuta-flutuante"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-resumo-minuta-flutuante"}],["meta",{"property":"og:title","content":"Painel de resumo da minuta | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-resumo-minuta-flutuante.md","filePath":"funcionalidades/eproc-resumo-minuta-flutuante.md"}'),n={name:"funcionalidades/eproc-resumo-minuta-flutuante.md"};function i(s,a,u,d,l,c){return o(),t("div",null,a[0]||(a[0]=[r('<h1 id="painel-de-resumo-da-minuta" tabindex="-1">Painel de resumo da minuta <a class="header-anchor" href="#painel-de-resumo-da-minuta" aria-label="Permalink to &quot;Painel de resumo da minuta&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Enquanto você redige uma minuta, mostra num painel flutuante os dados escolhidos no cadastro: localizadores, evento, intimação ou citação, destinatário, audiência, assinante e outros. Assim você confere tudo sem voltar à tela anterior.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de edição da minuta, depois do cadastro (&quot;Salvar e Editar&quot;) ou ao retomar uma minuta existente.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Cadastre a minuta normalmente e clique em <strong>Salvar e Editar</strong>.</li><li>Na edição do documento, o painel aparece com o resumo dos dados preenchidos.</li><li>Arraste o painel para onde preferir, ou fixe-o à direita da tela. Cada seção pode ser recolhida. A posição e as preferências são lembradas.</li><li>Para fechar, use o botão &quot;Fechar resumo&quot;. Para reabrir, use &quot;Mostrar resumo da minuta&quot;.</li></ol><h3 id="documentos-citados" tabindex="-1">Documentos citados <a class="header-anchor" href="#documentos-citados" aria-label="Permalink to &quot;Documentos citados&quot;">​</a></h3><p>Quando a minuta tem links para documentos do processo (como &quot;evento 1, INIC1&quot;), o painel ganha a seção <strong>Documentos citados</strong>, com um item por documento:</p><ul><li>clique no nome para rolar a minuta até o trecho que o cita. Se ele aparece mais de uma vez, cada clique leva à próxima menção;</li><li>clique no botão de abrir, ao lado, para abrir o documento;</li><li>um ícone de alerta aparece quando o link aponta para um documento de outro processo, o que costuma acontecer quando o texto foi copiado de outra minuta.</li></ul><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Ao abrir a edição sem dados de resumo, carregar &quot;Alterar Dados da Minuta&quot; em segundo plano para preencher o painel</td><td>ligada</td><td>Permite montar o resumo de minutas já existentes, sem abrir nada na tela.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O painel segue o tema claro ou escuro escolhido nas configurações do eploc.</li><li>A posição e o tamanho do painel ficam guardados no navegador, para cada endereço do eproc, e não entram no backup.</li></ul>',14)]))}const h=e(n,[["render",i]]);export{p as __pageData,h as default};
